def fib(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

# Tests
import pytest

@pytest.mark.parametrize("n, expected", [
    (0, 0),
    (1, 1),
    (2, 1),
    (10, 55),
    (0, 0)
])
def test_fib(n, expected):
    assert fib(n) == expected

if __name__ == "__main__":
    # Run manual tests
    for i in range(10):
        print(f"F({i}) = {fib(i)}")
